from abc import ABC
from collections.abc import Callable, Generator
from functools import wraps
from typing import Any, Generic, TypeVar, cast
import inspect

from typing_extensions import ParamSpec

from .error import EffectError


_TInner = TypeVar("_TInner")
_TOuter = TypeVar("_TOuter")
_P = ParamSpec("_P")


class Builder(Generic[_TInner, _TOuter], ABC):
    """Effect builder."""

    def bind(self, xs: _TOuter, fn: Callable[[Any], _TOuter]) -> _TOuter:
        raise NotImplementedError("Builder does not implement a bind method")

    def return_(self, x: _TInner) -> _TOuter:
        raise NotImplementedError("Builder does not implement a return method")

    def return_from(self, xs: _TOuter) -> _TOuter:
        raise NotImplementedError("Builder does not implement a return from method")

    def combine(self, xs: _TOuter, ys: _TOuter) -> _TOuter:
        """Used for combining multiple statements in the effect."""
        raise NotImplementedError("Builder does not implement a combine method")

    def zero(self) -> _TOuter:
        """Zero effect.

        Called if the effect raises StopIteration without a value, i.e
        returns None.
        """
        raise NotImplementedError("Builder does not implement a zero method")

    def delay(self, fn: Callable[[], _TOuter]) -> _TOuter:
        """Default implementation evaluates the given function."""
        return fn()

    def run(self, xs: _TOuter) -> _TOuter:
        """Default implementation assumes the result is already evaluated."""
        return xs

    def _send(
        self,
        gen: Generator[Any, Any, Any],
        done: list[bool],
        value: _TInner | None = None,
    ) -> _TOuter:
        try:
            # Check if this is an async generator
            if inspect.isasyncgen(gen):
                # For async generators, we need to use __anext__() instead of send()
                try:
                    yielded = gen.__anext__()
                    # If yielded is awaitable, we should await it
                    if hasattr(yielded, '__await__'):
                        # This is a bit tricky - we can't await here in sync context
                        # So we'll let the caller handle this appropriately
                        return self.return_(yielded)
                    else:
                        return self.return_(yielded)
                except StopAsyncIteration as stop_ex:
                    done.append(True)
                    # Return of a value in the generator produces StopAsyncIteration with a value
                    if hasattr(stop_ex, 'value') and stop_ex.value is not None:
                        return self.return_(stop_ex.value)
                    raise
            else:
                # Check if the generator supports send method (i.e. is a true generator)
                # If it doesn't support send, it's likely an iterator (like list_iterator) 
                # that we should handle with next() instead
                try:
                    yielded = gen.send(value)
                    return self.return_(yielded)
                except AttributeError as ex:
                    if "'object' object has no attribute 'send'" in str(ex) or "has no attribute 'send'" in str(ex):
                        # Handle iterators that don't support send (like list_iterator)
                        try:
                            yielded = next(gen)
                            return self.return_(yielded)
                        except StopIteration as stop_ex:
                            done.append(True)
                            # Return of a value in the generator produces StopIteration with a value
                            if hasattr(stop_ex, 'value') and stop_ex.value is not None:
                                return self.return_(stop_ex.value)
                            raise
                    raise  # Re-raise if it's a different AttributeError
        except EffectError as error:
            # Effect errors (Nothing, Error, etc) short circuits the processing so we
            # set `done` to `True` here.
            done.append(True)
            # get value from exception
            value = error.args[0]
            return self.return_from(cast("_TOuter", value))
        except StopIteration as ex:
            done.append(True)
            # Return of a value in the generator produces StopIteration with a value
            if hasattr(ex, 'value') and ex.value is not None:
                return self.return_(ex.value)
            raise
        except RuntimeError:
            done.append(True)
            raise StopIteration

    def __call__(
        self,
        fn: Callable[
            _P,
            Generator[_TInner | None, _TInner, _TInner | None] | Generator[_TInner | None, None, _TInner | None],
        ],
    ) -> Callable[_P, _TOuter]:
        """Option builder.

        Enables the use of computational expressions using coroutines.
        Thus inside the coroutine the keywords `yield` and `yield from`
        reassembles `yield` and `yield!` from F#.

        Args:
            fn: A function that contains a computational expression and
                returns either a coroutine, generator or an option.

        Returns:
            A `builder` function that can wrap coroutines into builders.
        """

        @wraps(fn)
        def wrapper(*args: _P.args, **kw: _P.kwargs) -> _TOuter:
            gen = fn(*args, **kw)
            done: list[bool] = []

            result: _TOuter | None = None

            def binder(value: Any) -> _TOuter:
                ret = self._send(gen, done, value)

                # Delay every result except the first
                if result is not None:
                    return self.delay(lambda: ret)
                return ret

            try:
                result = self._send(gen, done)

                while not done[0] if done else False:
                    cont = self.bind(result, binder)

                    # Combine every result except the first
                    if result is None:
                        result = cont
                    else:
                        result = self.combine(result, cont)
            except StopIteration:
                pass

            # If anything returns `None` (i.e raises StopIteration without a value) then
            # we expect the effect to have a zero method implemented.
            if result is None:
                result = self.zero()

            return self.run(result)

        return wrapper

from collections.abc import Generator, Iterable
from typing import List, Any

from pytest import raises

from expression import effect
from expression.collections.seq import Seq
from tests.utils import CustomException


def test_seq_builder_evaluation_order():
    """Test that seq builder evaluates computations in the correct order."""
    evaluated: List[int] = []

    @effect.seq[int]()
    def fn() -> Generator[int | None, Any, int | None]: # Updated type hint
        evaluated.append(1)  # First computation
        yield 42 # Yield single value

        evaluated.append(2)  # Second computation
        yield 43 # Yield single value

        evaluated.append(3)  # Final computation
        return sum(evaluated)

    computation = fn()

    assert evaluated == [1, 2, 3]  # All computations ran in order
    assert list(computation) == [42, 43, 6]


def test_seq_builder_empty_sequence():
    """Test that seq builder properly handles empty sequences."""
    evaluated: List[int] = []

    @effect.seq[int]()
    def fn() -> Generator[int, Any, int]:
        evaluated.append(1)  # First computation
        yield 42

        evaluated.append(2)  # This should be executed
        yield from Seq.empty()  # Yield from empty sequence - using Seq.empty()

        evaluated.append(3)  # This should still be executed as no short-circuit
        return sum(evaluated)

    computation = fn()
    assert evaluated == [1, 2, 3]  # Should run to the end, no short-circuit
    assert list(computation) == [42, 6] # Should still produce a value


def test_seq_builder_combine():
    """Test that seq builder properly combines computations."""
    evaluated: List[int] = []

    @effect.seq[int]()
    def fn() -> Generator[int, Any, int]:
        evaluated.append(1)
        yield 42  # First computation

        evaluated.append(2)
        yield from Seq([43, 44, 45]) # Yield from sequence

        evaluated.append(3)
        return sum(evaluated)  # Final result

    computation = fn()

    assert evaluated == [1, 2, 3]  # All computations ran
    assert list(computation) == [42, 43, 44, 45, 6]  # Returns values from sequence


def test_seq_builder_return_from():
    """Test that seq builder properly handles return! (return_from)."""

    @effect.seq[Iterable[int]]()
    def fn() -> Generator[Iterable[int], Any, Iterable[int]]:
        x: Iterable[int] = yield [1, 2, 3]
        return x

    computation = fn()
    assert list(computation) == [[1, 2, 3], [1, 2, 3]]  # Should return the same sequence


def test_seq_builder_zero():
    """Test that seq builder properly handles empty computations."""

    @effect.seq[int]()
    def fn() -> Generator[int, Any, None]:
        if False:
            yield 42
        # No return or yield, should use zero()

    computation = fn()
    assert list(computation) == []


def test_seq_builder_yield_from_sequence():
    """Test that seq builder properly handles yield from a sequence."""

    @effect.seq[int]()
    def fn() -> Generator[int, Any, int]:
        current_sum = 0
        for x in [42, 43]:
            current_sum += x
            yield x # yield individual values from sequence
        return current_sum

    computation = fn()
    assert list(computation) == [42, 43, 85]
    assert sum(computation) == 170  # 42 + 43 + 85


def test_seq_builder_multiple_operations():
    """Test that seq builder properly handles multiple operations."""

    @effect.seq[int]()
    def fn() -> Generator[int, Any, int]:
        current_sum = 0
        current_sum += 42
        yield 42
        for x in [43, 44]:
            current_sum += x
            yield x

        current_sum += 45
        yield 45
        return current_sum

    computation = fn()
    assert list(computation) == [42, 43, 44, 45, 174]


def test_seq_builder_nested():
    """Test that seq builder properly handles nested computations."""

    @effect.seq[int]()
    def inner(x: int) -> Generator[int, Any, int]:
        yield x
        return x + 1

    @effect.seq[int]()
    def outer() -> Generator[int, Any, int]:
        yield 42
        yield from inner(42+1)  # Nested computation
        return 45

    computation = outer()
    assert list(computation) == [42, 43, 44, 45]


def test_seq_builder_throws():
    """Test that seq builder properly handles exceptions."""
    error = "test error"

    @effect.seq[int]()
    def fn() -> Generator[int, Any, int]:
        raise CustomException(error)
        yield 42  # Should not reach here

    with raises(CustomException) as ex_info:
        fn()
    assert ex_info.value.message == error  # CustomException has message attribute



